ckground:#2a2a2a;color:#fff;padding:1rem;display:flex;flex-direction:column;justify-content:center;text-align:center} .cb-l li>div:first-child b{font-family:"Fraunces",serif;font-size:1.9rem;line-height:1} .cb-l li>div:first-child span{font-size:.75rem;opacity:.8;margin-top:.3rem} .cb-l li.past>div:first-child{background:#9a948a} .cb-l li.now>div:first-child{background:#c43d2b} .cb-l li>div+div{padding:1rem 1.2rem} .cb-l h3{font-family:"Fraunces",serif!important;font-size:1.2rem!important;margin:0 0 .3rem!important;color:#2a2a2a!important} .cb-l p{margin:0;font-size:.88rem;line-height:1.5;color:#5b554c} @media (max-width:860px){.cb-in{grid-template-columns:1fr}}</style><section class="op cb"><div class="cb-in"><div class="op-rv"><h2>Votre compte à rebours</h2><p>Indiquez votre date de départ : on vous dit quoi faire, et quand.</p><div class="cb-f"><label for="cbD">Je pars le…</label><input type="date" id="cbD"></div><div class="cb-big" id="cbN"></div></div><ol class="cb-l" id="cbL"><li data-j="42"><div><b>J-42</b><span id="cb42">6 semaines</span></div><div><h3>Vaccins et passeport</h3><p>Rendez-vous de vaccination (fièvre jaune), vérification du passeport, demande d’e-visa, assurance.</p></div></li><li data-j="14"><div><b>J-14</b><span id="cb14">2 semaines</span></div><div><h3>Santé, réservations, banque</h3><p>Antipaludique prescrit, hébergements confirmés, banque prévenue de votre voyage.</p></div></li><li data-j="1"><div><b>J-1</b><span id="cb1">la veille</span></div><div><h3>Documents et valise</h3><p>E-visa imprimé, carnet de vaccination avec le passeport, copies envoyées par courriel, petites coupures.</p></div></li></ol></div></section><script>(function(){var d=document.getElementById("cbD"),n=document.getElementById("cbN");function f(x){return x.toLocaleDateString("fr-FR",{day:"numeric",month:"long"})}function u(){if(!d.value){n.innerHTML="";return}var dep=new Date(d.value+"T00:00:00"),now=new Date();now.setHours(0,0,0,0);var r=Math.round((dep-now)/864e5);n.innerHTML=r>0?r+"<small>jours avant le grand départ</small>":r===0?"Jour J<small>bon voyage !</small>":"";var found=false;document.querySelectorAll("#cbL li").forEach(function(li){var j=+li.dataset.j,t=new Date(dep);t.setDate(t.getDate()-j);document.getElementById("cb"+j).textContent=f(t);li.classList.toggle("past",r>=0&&r<j);if(r>=j&&!found){li.classList.add("now");found=true}else li.classList.remove("now");});try{localStorage.setItem("ba-depart",d.value)}catch(e){}}try{var s=localStorage.getItem("ba-depart");if(s)d.value=s}catch(e){}d.addEventListener("change",u);u()})();</script><script>(function(){function go(){var e=document.querySelectorAll(".op-rv:not(.on)");if(!("IntersectionObserver" in window)){e.forEach(function(x){x.classList.add("on")});return}var o=new IntersectionObserver(function(n){n.forEach(function(x){if(x.isIntersecting){x.target.classList.add("on");o.unobserve(x.target)}})},{threshold:.1});e.forEach(function(x){o.observe(x)})}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",go);else go()})();</script>

            
                                        
            
            
            
                                        
